from django.db import migrations, models

# Secuencia de unidades usada para convertir los tramos existentes por MONTO
# (`min_amount`) a tramos por CANTIDAD (`min_quantity`) — decisión del dueño:
# 5 unidades -> 5% OFF, 10 unidades -> 10% OFF, 20 unidades -> 15% OFF. Si
# alguna marca llegara a tener más de 3 tramos configurados, se sigue
# sumando de 10 en 10 a partir del último valor conocido (caso no real hoy,
# solo defensivo).
QUANTITY_SEQUENCE = [5, 10, 20]


def _quantity_for_index(i):
    if i < len(QUANTITY_SEQUENCE):
        return QUANTITY_SEQUENCE[i]
    return QUANTITY_SEQUENCE[-1] + 10 * (i - len(QUANTITY_SEQUENCE) + 1)


def convertir_tramos_a_cantidad(apps, schema_editor):
    """Los tramos existentes estaban keyeados por `min_amount` (monto en $
    del subtotal). El nuevo mecanismo es por `min_quantity` (cantidad de
    unidades) — no hay forma de derivar matemáticamente una cantidad desde
    un monto en $ (depende del precio de cada producto), así que se
    reasignan en el mismo orden ascendente que ya tenían, usando la
    secuencia de unidades acordada con el dueño. El `discount_percent` de
    cada tramo no se toca."""
    Brand = apps.get_model("brands", "Brand")
    for brand in Brand.objects.exclude(cart_discount_config=[]):
        tiers = brand.cart_discount_config or []
        if not tiers or not any("min_amount" in t for t in tiers):
            continue
        sorted_tiers = sorted(tiers, key=lambda t: t.get("min_amount", 0))
        brand.cart_discount_config = [
            {
                "min_quantity": _quantity_for_index(i),
                "discount_percent": tier.get("discount_percent", 0),
            }
            for i, tier in enumerate(sorted_tiers)
        ]
        brand.save(update_fields=["cart_discount_config"])


